<template><section><div class="page-head"><div><span class="eyebrow">Add-on library</span><h1 class="page-title">Repository</h1><p class="muted">Available LogoRemakeFour add-ons.</p></div><button class="button-secondary" @click="$emit('navigate','addons')">← Add-ons</button></div><div class="grid"><article v-for="addon in state.addons" :key="addon.id" class="card"><span class="tile-icon">{{addon.icon}}</span><h3>{{addon.name}}</h3><p class="muted">{{addon.description}}</p><button class="button" @click="$emit('action',{action:state.installed.includes(addon.id)?'open-addon':'install',payload:addon.id})">{{state.installed.includes(addon.id)?'Open':'Install'}}</button></article></div></section></template>
